# =============================================================================
# ERROR HANDLING MESH
# =============================================================================

class MathSolverError(Exception):
    """Base exception for MathSolver engine."""
    def __init__(self, message: str, code: str):
        super().__init__(message)
        self.code = code

class SyntaxErrorMesh(MathSolverError):
    def __init__(self, msg="Malformed expression"): super().__init__(msg, "ERR_001")

class DomainErrorMesh(MathSolverError):
    def __init__(self, msg="Domain violation detected"): super().__init__(msg, "ERR_002")

class ConvergenceErrorMesh(MathSolverError):
    def __init__(self, msg="Numerical loop failed to stabilize"): super().__init__(msg, "ERR_003")

class ComplexityErrorMesh(MathSolverError):
    def __init__(self, msg="Expression depth exceeds limit"): super().__init__(msg, "ERR_004")

class ParameterErrorMesh(MathSolverError):
    def __init__(self, msg="Missing required symbol"): super().__init__(msg, "ERR_005")

# =============================================================================
# TYPES & MODELS
# =============================================================================

class SolverMode(Enum):
    SYMBOLIC = "SYMBOLIC"
    NUMERICAL = "NUMERICAL"
    AUTO = "AUTO"

@dataclass
class SolverResult:
    exact: Optional[str] = None
    approximate: Optional[float] = None
    unit: Optional[str] = None

@dataclass
class SolverMetadata:
    execution_time_ms: float
    method_used: str
    complexity_score: str
    steps: List[str]

# =============================================================================
# ENGINE IMPLEMENTATIONS
# =============================================================================

class SymbolicEngine:
    """Handles Computer Algebra System (CAS) operations."""
    
    def solve(self, expression_str: str, variables: Dict[str, Any]) -> Tuple[sympy.Expr, List[str]]:
        steps = []
        try:
            # Parse expression into SymPy AST
            expr = sympify(expression_str)
            steps.append(f"Parsed expression into AST: {expr}")
            
            # Handle specific functional wrappers (e.g., integrate(f, x))
            if expression_str.startswith("integrate"):
                # Simple regex-like split for the example 'integrate(expr, var)'
                content = expression_str[expression_str.find("(")+1 : expression_str.rfind(")")]
                parts = [p.strip() for p in content.split(",")]
                if len(parts) == 2:
                    target_expr = sympify(parts[0])
                    var_sym = Symbol(parts[1])
                    result = integrate(target_expr, var_sym)
                    steps.append(f"Applied IntegrationByParts/Symbolic Integration on {var_sym}")
                    return simplify(result), steps
            
            # Default to simplification
            result = simplify(expr)
            steps.append("Applied canonical simplification and GCD reduction.")
            return result, steps
            
        except sympy.SympifyError:
            raise SyntaxErrorMesh()
        except Exception as e:
            raise DomainErrorMesh(str(e))

class NumericalEngine:
    """Handles high-precision floating point compute."""
    
    def solve(self, expression_str: str, variables: Dict[str, Any], precision: int) -> float:
        mpmath.mp.dps = precision
        try:
            # Substitute variables into the expression
            # We use sympy to evaluate the expression numerically via mpmath
            expr = sympify(expression_str)
            
            # Create substitution map
            subs_map = {Symbol(k): v for k, v in variables.items()}
            
            # Evaluate using mpmath for high precision
            # lambda_func converts sympy expr to a callable
            f = sympy.lambdify(list(subs_map.keys()), expr, 'mpmath')
            
            # Handle case where there are no variables
            if not subs_map:
                val = mpmath.evalf(expr)
            else:
                val = f(*subs_map.values())
                
            return float(val)
        except (ValueError, ZeroDivisionError):
            raise DomainErrorMesh("Numerical evaluation encountered a domain violation (e.g. 1/0).")
        except Exception:
            raise ConvergenceErrorMesh()

# =============================================================================
# SOLVER DISPATCHER & API GATEWAY
# =============================================================================

class MathSolver:
    """
    High-Precision Symbolic and Numerical Computation Engine.
    Implements the layered execution pipeline defined in the Architectural Blueprint.
    """
    
    def __init__(self):
        self.symbolic_engine = SymbolicEngine()
        self.numerical_engine = NumericalEngine()
        self.logger = logging.getLogger("MathSolver")

    def execute(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        start_time = time.perf_counter()
        
        # 1. Input Extraction & Validation
        expression = payload.get("expression")
        if not expression:
            return {"status": "ERROR", "error_code": "ERR_001", "message": "Expression is required"}
            
        mode = SolverMode(payload.get("mode", "SYMBOLIC"))
        variables = payload.get("variables", {})
        precision = payload.get("precision", 15)
        timeout_ms = payload.get("timeout", 5000)
        constraints = payload.get("constraints", [])

        try:
            # 2. Dispatching Logic
            result_obj = SolverResult()
            metadata_obj = SolverMetadata(
                execution_time_ms=0, 
                method_used="Unknown", 
                complexity_score="O(1)", 
                steps=[]
            )

            # AUTO Mode Heuristic: Try symbolic, fallback to numerical
            if mode == SolverMode.AUTO:
                try:
                    sym_res, steps = self.symbolic_engine.solve(expression, variables)
                    result_obj.exact = str(sym_res)
                    metadata_obj.method_used = "HeuristicAuto -> Symbolic"
                    metadata_obj.steps = steps
                except (DomainErrorMesh, ComplexityErrorMesh):
                    # Fallback to numerical
                    val = self.numerical_engine.solve(expression, variables, precision)
                    result_obj.approximate = val
                    metadata_obj.method_used = "HeuristicAuto -> Numerical"
                    metadata_obj.steps = ["Symbolic path failed; fell back to numerical approximation."]
            
            elif mode == SolverMode.SYMBOLIC:
                sym_res, steps = self.symbolic_engine.solve(expression, variables)
                result_obj.exact = str(sym_res)
                metadata_obj.method_used = "SymbolicCAS"
                metadata_obj.steps = steps
                
            elif mode == SolverMode.NUMERICAL:
                val = self.numerical_engine.solve(expression, variables, precision)
                result_obj.approximate = val
                metadata_obj.method_used = "IterativeNumerical"
                metadata_obj.steps = ["Evaluated expression using high-precision floating point arithmetic."]

            # 3. Post-Processing & Variable Substitution for Numerical Result
            # If we have an exact result but requested numerical, or just to provide both:
            if result_obj.exact and not result_obj.approximate:
                try:
                    # Evaluate the exact result numerically
                    exact_expr = sympify(result_obj.exact)
                    subs_map = {Symbol(k): v for k, v in variables.items()}
                    num_val = exact_expr.evalf(subs=subs_map, n=precision)
                    result_obj.approximate = float(num_val)
                except:
                    pass

            # 4. Finalize Metadata
            end_time = time.perf_counter()
            metadata_obj.execution_time_ms = (end_time - start_time) * 1000
            
            return {
                "status": "SUCCESS",
                "result": asdict(result_obj),
                "metadata": asdict(metadata_obj)
            }

        except MathSolverError as e:
            return {
                "status": "ERROR",
                "error_code": e.code,
                "message": str(e)
            }
        except Exception as e:
            self.logger.error(f"Unexpected System Failure: {str(e)}")
            return {
                "status": "ERROR",
                "error_code": "ERR_SYSTEM",
                "message": "An internal engine error occurred."
            }

